const bus = new EventEmitter();

app.get('/events', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  bus.on('alert', (payload) => {
    res.write(`data: ${JSON.stringify(payload)}\n\n`);
  });
});

solution:
Each incoming client registers a closure capturing `res` on the global `bus` without ever removing it when the client disconnects.

Fix:
```js
app.get('/events', (req, res) => {
  res.setHeader('Content-Type', 'text/event-stream');
  res.setHeader('Cache-Control', 'no-cache');
  res.flushHeaders();

  const onAlert = (payload) => {
    if (!res.writableEnded) {
      res.write(`data: ${JSON.stringify(payload)}\n\n`);
    }
  };

  bus.on('alert', onAlert);
  req.on('close', () => {
    bus.off('alert', onAlert);
    res.end();
  });
});
```

codeSnippet:
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  const payload = jwt.decode(token);
  if (!payload) return res.status(401).end();
  req.user = payload;
  next();
}

solution:
Flaws: (1) `jwt.decode()` never verifies the signature — anyone can base64-encode `{ role: 'admin' }`. (2) No algorithm pinning (`algorithms: ['HS256']` or `['RS256']`), risking algorithm confusion. (3) No `iss`/`aud` validation or expiry error handling.

Fix:
```js
function authMiddleware(req, res, next) {
  const header = req.headers.authorization || '';
  if (!header.startsWith('Bearer ')) return res.status(401).json({ error: 'Missing token' });
  const token = header.slice(7).trim();
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
      issuer: 'bca-verse-auth',
      audience: 'bca-verse-api',
    });
    req.user = payload;
    return next();
  } catch {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}
```

